/* outer /* inner */ still outer */
@group(0) @binding(0) var<uniform> u: Uniforms; // trailing @binding(9)
struct Uniforms { a: f32, /* b: f32, */ }
@fragment fn main() -> @location(0) vec4f { return vec4f(u.a); }

@group(0) @binding(0) var unusedTex: texture_2d<f32>;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var inputTex: texture_2d<f32>;
@group(0) @binding(3) var<storage, read_write> buf: array<f32>;
@group(0) @binding(4) var outTex: texture_storage_2d<rgba16float, write>;
@group(1) @binding(0) var inputTex2: texture_2d<f32>;
@fragment fn main(@location(0) uv: vec2f) -> @location(0) vec4f { return textureSample(inputTex, samp, uv); }

@group(0) @binding(0) var texA: texture_2d<f32>;
@group(0) @binding(1) var texB: texture_2d<f32>;
@group(0) @binding(2) var s: sampler;
@group(0) @binding(3) var<uniform> u: U;
struct U { t: f32 }
fn helper(texB: f32) -> f32 { return texB + u.t; }
fn sampleA(p: vec2f) -> vec4f { return textureSample(texA, s, p); }
fn shadow() -> f32 { let texA = 1.0; for (var i = 0; i < 3; i++) { let texB = 2.0; } return texA + x.texB; }
@fragment
fn main(@builtin(position) pos: vec4f) -> @location(0) vec4f {
  let a = sampleA(pos.xy) + vec4f(helper(1.0));
  var<function> texB: f32 = shadow();
  return a * texB;
}
@vertex fn vs(@builtin(vertex_index) i: u32) -> @builtin(position) vec4f { return vec4f(textureLoad(texB, vec2i(0), 0).x); }

@group(0) @binding(0) var<storage, read_write> data: array<vec4f>;
@group(0) @binding(1) var outTex: texture_storage_2d<rgba16float, write>;
@compute @workgroup_size(8, 8, 1)
fn first(@builtin(global_invocation_id) id: vec3u) { data[id.x] = vec4f(0.0); }
@compute
@workgroup_size(64)
fn second(@builtin(global_invocation_id) gid: vec3<u32>) { textureStore(outTex, vec2i(gid.xy), data[gid.x]); }

struct Params { time: f32, resolution: vec2f, _pad0: f32, color: vec3<f32>, count: i32, padding: vec2<u32>, tint: VEC4F }
@group(0) @binding(0) var<uniform> p: Params;
@fragment fn main() -> @location(0) vec4f { return vec4f(p.color * p.time, f32(p.count)); }

struct Params { time: f32 }
@group(0) @binding(0) var<uniform> p: Params;
@fragment fn main() -> @location(0) vec4f { return vec4f(1.0); }

struct FooParams {
    dims : vec4<f32>,  // (width, height, _, pad0)
    settings : vec4<f32>,   // (octaves, unused1, speed, seed)
    count : i32,
    extra : vec2<f32>, // (a)
    table : array<vec4<f32>, 4>,
}
@group(0) @binding(0) var<uniform> params: FooParams;
@fragment fn main() -> @location(0) vec4f { return params.dims; }

struct BarParams { a: vec4<f32>, b: vec4<f32>, c: f32 }
@group(0) @binding(0) var<uniform> params: BarParams;
@fragment fn main() -> @location(0) vec4f {
  let speed = params.b.y;
  let freq: f32 = params.a.w;
  octaves = i32( params.a.x);
  let missing = params.zz.x;
  return vec4f(speed, freq, 0.0, 1.0);
}

struct Uniforms { data: array<vec4<f32>, 4> }
@group(0) @binding(0) var<uniform> uniforms: Uniforms;
@fragment fn main() -> @location(0) vec4f {
  let scale = uniforms.data[2].w;
  resolution = uniforms.data[0].xy;
  let count: i32 = max(1, i32(uniforms.data[1].z));
  let mode = i32(uniforms.data[1].x);
  let flag = uniforms.data[0].z > 0.5;
  return vec4f(scale);
}

struct myPARAMS { Speed: F32, Count: I32 }
@group(0) @binding(0) var<uniform> m: myPARAMS;
@fragment fn main() -> @location(0) vec4f { return vec4f(m.Speed); }

// π ≈ 3.14159 — comment with non-ASCII
@group(0) @binding(1) var tex: texture_2d<f32>;
@group(0) @binding(2) var s: sampler;
/* ∑ é */ @fragment fn main(@location(0) uv: vec2f) -> @location(0) vec4f { return textureSample(tex, s, uv); }

@group(0) @binding(0) var a: texture_2d<f32>;
@group(0) @binding(1) var b: texture_2d<f32>;
@group(0) @binding(2) var shared: sampler;
@group(0) @binding(3) var only: sampler;
@fragment fn main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let x = textureSample(a, shared, uv) + textureSampleLevel(b, shared, uv, 0.0);
  return x + textureSample(a, only, uv) + textureSampleBias( a , only , uv, 1.0);
}

struct Big { m: mat4x4<f32>, v: vec3f, arr: array<vec2<f32>, 3>, h: f16, b: bool }
struct Small { x: f32 }
@group(0) @binding(0) var<uniform> big: Big;
@group(0) @binding(1) var<uniform> small: Small;
@fragment fn main() -> @location(0) vec4f { return vec4f(big.v, small.x); }
